package com.brightloop.model;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDate;
@Entity public class Subscription { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(nullable=false,unique=true) public String number; @ManyToOne(optional=false) public Customer customer; @ManyToOne(optional=false) public Plan plan; public LocalDate startDate; public LocalDate expiryDate; public String paymentTerms; @Enumerated(EnumType.STRING) public Status status=Status.DRAFT; public int quantity=1; public BigDecimal unitPrice=BigDecimal.ZERO; public BigDecimal taxRate=new BigDecimal("0.18"); public BigDecimal discountAmount=BigDecimal.ZERO; public LocalDate nextBillingDate; public Long discountRuleId; public LocalDate validUntil; public enum Status{DRAFT,QUOTATION,CONFIRMED,ACTIVE,PAUSED,CLOSED} }
